import base64
import hashlib

SHA256 = "0ddfef896b3ad640463eaf79ae79826d501d946eae3ce2b66f40ca5c7ee19956"
PAYLOAD = ""

def archive() -> bytes:
    data = base64.b64decode(PAYLOAD, validate=True)
    if hashlib.sha256(data).hexdigest() != SHA256:
        raise ValueError("ACPI payload checksum mismatch")
    return data

